fn frame(t: i32) {
    host::display::clear(0x000008);
    let cx: i32 = host::display::width() / 2;
    let cy: i32 = host::display::height() / 2;
    let mut a: i32 = 0;
    while a < 256 {
        let ox: i32 = cx + (120 * host::math::cos(a)) / 256;
        let oy: i32 = cy + (120 * host::math::sin(a)) / 256;
        host::display::set_pixel(ox, oy, 0x223344);
        a = a + 4;
    }
    host::display::fill_rect(cx - 10, cy - 10, 20, 20, 0xffcc33);
    let px: i32 = cx + (120 * host::math::cos(t)) / 256;
    let py: i32 = cy + (120 * host::math::sin(t)) / 256;
    host::display::fill_rect(px - 6, py - 6, 12, 12, 0x3399ff);
    let mx: i32 = px + (24 * host::math::cos(t * 4)) / 256;
    let my: i32 = py + (24 * host::math::sin(t * 4)) / 256;
    host::display::fill_rect(mx - 2, my - 2, 5, 5, 0xbbbbbb);
    host::display::present();
}
